class TaskBinding{static Object value(long m,long n){return new Rational(m,n);}static long[]parts(Object x){return new long[]{((Rational)x).numerator(),((Rational)x).denominator()};}static Object operation(Object a,Object b,int op){Rational x=(Rational)a,y=(Rational)b;return switch(op){case 0->x.add(y);case 1->x.subtract(y);case 2->x.multiply(y);default->x.divide(y);};}static Object[]array(Object...a){return java.util.Arrays.copyOf(a,a.length,Rational[].class);}static void transform(Object[]a){Rational.transform((Rational[])a);}}
